/* tool call */
#tlc{padding:14px 0}
.tlc-msg{padding:0 16px 12px;font-size:14px;line-height:1.5}
.tlc-end{padding:12px 16px 0;opacity:0;transform:translateY(4px);transition:opacity .4s,transform .4s var(--ease)}
.tlc-end.in{opacity:1;transform:none}
.tlc-call{margin:0 16px 8px;border:1px solid var(--line);background:var(--surface)}
.tlc-h{display:flex;align-items:center;gap:10px;width:100%;padding:9px 12px;text-align:left;font-size:13px}
.tlc-st{width:18px;height:18px;flex:none;display:grid;place-items:center;color:var(--muted)}
.tlc-n{flex:1;min-width:0;font-family:var(--mono);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tlc-ms{font-size:10px}
.tlc-h .chev{color:var(--muted);transition:transform .3s var(--ease)}
.tlc-call.open .chev{transform:rotate(180deg)}
.tlc-b{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s var(--ease)}
.tlc-b>div{overflow:hidden}
.tlc-call.open .tlc-b{grid-template-rows:1fr}
.tlc-io{padding:4px 12px 12px;border-top:1px solid var(--line)}
.tlc-lbl{font-family:var(--mono);font-size:10px;font-weight:700;text-transform:uppercase;color:var(--muted);margin:8px 0 4px}
.tlc-io pre{margin:0;padding:8px 10px;background:var(--chip);font-family:var(--mono);font-size:11px;line-height:1.6;white-space:pre-wrap;word-break:break-word;color:var(--text)}
.tlc-io .k{color:var(--code-k)}.tlc-io .s{color:var(--code-s)}.tlc-io .n{color:var(--code-f)}

/* ---------- tool call ---------- */
{
  const root = $('#tlc'), calls = $$('.tlc-call', root), end = $('#tlc-end');
  const times = ['412 ms', '1.2 s'];
  let ts = [];
  calls.forEach(c => c.querySelector('.tlc-h').addEventListener('click', () => {
    const on = !c.classList.contains('open'); c.classList.toggle('open', on);
    c.querySelector('.tlc-h').setAttribute('aria-expanded', on); Sound.play('tab');
  }));
  function run(){
    ts.forEach(clearTimeout); ts = []; end.classList.remove('in');
    calls.forEach(c => { c.classList.remove('open'); c.querySelector('.tlc-st').innerHTML = ic('terminal', 'sm'); c.querySelector('.tlc-ms').textContent = 'Queued'; });
    calls.forEach((c, i) => {
      ts.push(setTimeout(() => { c.querySelector('.tlc-st').innerHTML = '<i class="spin"></i>'; swapText(c.querySelector('.tlc-ms'), 'Running'); }, 300 + i * 1500));
      ts.push(setTimeout(() => {
        c.querySelector('.tlc-st').innerHTML = ic('check_circle', 'sm icon-in s-done'); swapText(c.querySelector('.tlc-ms'), times[i]);
        ambient('c107', 'tick');
        if (i === calls.length - 1){ end.classList.add('in'); calls[0].classList.add('open'); Sound.play('done'); }
      }, 1300 + i * 1500));
    });
  }
  $('#tlc-play').addEventListener('click', () => { Sound.play('tab'); run(); });
  whenSeen($('#c107'), run);
}
